faultyFiles./src/styles.css:
body {
  font-family: sans-serif;
  -webkit-font-smoothing: auto;
  -moz-font-smoothing: auto;
  -moz-osx-font-smoothing: grayscale;
  font-smoothing: auto;
  text-rendering: optimizeLegibility;
  font-smooth: always;
  -webkit-tap-highlight-color: transparent;
  -webkit-touch-callout: none;
  margin: 0;
}

h1 {
  font-size: 1.5rem;
}

.signup-page {
  box-sizing: border-box;
  max-width: 420px;
  min-width: 0;
  margin: 0 auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hint {
  margin: 0;
  color: #555;
  font-size: 0.9rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.field-label {
  font-size: 0.9rem;
  color: #333;
}

.name-input {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 8px 10px;
  font-size: 1rem;
  border: 1px solid #bbb;
  border-radius: 6px;
}

.submit-button {
  box-sizing: border-box;
  align-self: flex-start;
  padding: 8px 20px;
  font-size: 1rem;
  color: #fff;
  background-color: #2f6fed;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}

.submit-button:disabled {
  background-color: #a9bde8;
  cursor: not-allowed;
}

